begin;

create table public.learning_weeks (
  number integer primary key check(number between 1 and 26),
  month integer not null check(month between 1 and 6),
  title text not null,
  milestone boolean not null default false,
  prerequisite text not null default ''
);
create table public.learning_criteria (
  id text primary key,
  week_number integer not null references public.learning_weeks(number),
  kind text not null check(kind in ('topic','practice','acceptance')),
  position integer not null,
  label text not null,
  unique(week_number,position)
);
create table public.learning_projects (
  id text primary key,
  title text not null,
  description text not null,
  start_week integer not null references public.learning_weeks(number),
  end_week integer not null references public.learning_weeks(number),
  check(end_week>=start_week)
);
create table public.learning_checks (
  user_id uuid not null references auth.users(id) on delete cascade,
  criterion_id text not null references public.learning_criteria(id),
  completed_at timestamptz not null default now(),
  primary key(user_id,criterion_id)
);
create table public.learning_evidence (
  user_id uuid not null references auth.users(id) on delete cascade,
  week_number integer not null references public.learning_weeks(number),
  notes text not null default '' check(length(notes)<=8000),
  url text not null default '' check(url='' or (length(url)<=2000 and url ~ '^https?://[^[:space:]]+$')),
  updated_at timestamptz not null default now(),
  primary key(user_id,week_number)
);
create table public.learning_project_evidence (
  user_id uuid not null references auth.users(id) on delete cascade,
  project_id text not null references public.learning_projects(id),
  notes text not null default '' check(length(notes)<=8000),
  url text not null default '' check(url='' or (length(url)<=2000 and url ~ '^https?://[^[:space:]]+$')),
  updated_at timestamptz not null default now(),
  primary key(user_id,project_id)
);

