do $$
declare table_name text;
begin
  foreach table_name in array array['learning_weeks','learning_criteria','learning_projects']loop
    execute format('alter table public.%I enable row level security',table_name);
    execute format('revoke all on public.%I from public,anon,authenticated',table_name);
    execute format('grant select on public.%I to authenticated',table_name);
    execute format('create policy "Read curriculum" on public.%I for select to authenticated using(true)',table_name);
  end loop;
  foreach table_name in array array['learning_checks','learning_evidence','learning_project_evidence']loop
    execute format('alter table public.%I enable row level security',table_name);
    execute format('revoke all on public.%I from public,anon,authenticated',table_name);
    execute format('grant select on public.%I to authenticated',table_name);
    execute format('create policy "Read own learning records" on public.%I for select to authenticated using((select auth.uid())=user_id)',table_name);
  end loop;
end $$;

-- Private writes go through the guarded functions below. No direct table
-- writes are granted, so REST requests cannot bypass prerequisite checks.
create function public.learning_week_unlocked(p_week integer)
returns boolean language sql stable security invoker set search_path='' as $$
  select auth.uid() is not null and exists(select 1 from public.learning_weeks where number=p_week)
    and not exists(
      select 1 from public.learning_criteria c where c.week_number<p_week
      and not exists(select 1 from public.learning_checks done where done.user_id=auth.uid() and done.criterion_id=c.id)
    );
$$;

create function public.set_learning_check(p_criterion text,p_done boolean)
returns void language plpgsql security definer set search_path='' as $$
declare owner_id uuid:=auth.uid(); target public.learning_criteria%rowtype;
begin
  if owner_id is null then raise exception 'Sign in first';end if;
  if p_done is null then raise exception 'Choose a completion state';end if;
  insert into public.profiles(id) values(owner_id) on conflict do nothing;
  perform 1 from public.profiles where id=owner_id for update;
  select * into target from public.learning_criteria where id=p_criterion;
  if not found then raise exception 'Unknown checklist item';end if;
  if not public.learning_week_unlocked(target.week_number) then raise exception 'Complete all earlier weeks before editing this week';end if;
  if p_done and target.kind='acceptance' and not exists(
    select 1 from public.learning_evidence where user_id=owner_id and week_number=target.week_number and (length(trim(notes))>0 or url<>'')
  )then raise exception 'Save deliverable notes or a link before confirming the acceptance criteria';end if;
  if p_done then
    insert into public.learning_checks(user_id,criterion_id)values(owner_id,p_criterion)on conflict do nothing;
  else
    delete from public.learning_checks where user_id=owner_id and criterion_id=p_criterion;
  end if;
end;
$$;

create function public.save_learning_evidence(p_week integer,p_notes text,p_url text)
returns void language plpgsql security definer set search_path='' as $$
declare owner_id uuid:=auth.uid();
begin
  if owner_id is null then raise exception 'Sign in first';end if;
  insert into public.profiles(id) values(owner_id) on conflict do nothing;
  perform 1 from public.profiles where id=owner_id for update;
  if not public.learning_week_unlocked(p_week)then raise exception 'Complete all earlier weeks before editing this week';end if;
  if p_notes is null or p_url is null then raise exception 'Notes and URL must be text';end if;
  if length(trim(p_notes))=0 and length(trim(p_url))=0 and exists(
    select 1 from public.learning_checks done join public.learning_criteria c on c.id=done.criterion_id
    where done.user_id=owner_id and c.week_number=p_week and c.kind='acceptance'
  )then raise exception 'Reopen acceptance criteria before removing all deliverable evidence';end if;
  insert into public.learning_evidence(user_id,week_number,notes,url) values(owner_id,p_week,trim(p_notes),trim(p_url))
  on conflict(user_id,week_number)do update set notes=excluded.notes,url=excluded.url,updated_at=now();
end;
$$;

create function public.save_learning_project(p_project text,p_notes text,p_url text)
returns void language plpgsql security definer set search_path='' as $$
declare owner_id uuid:=auth.uid(); first_week integer;
begin
  if owner_id is null then raise exception 'Sign in first';end if;
  insert into public.profiles(id) values(owner_id) on conflict do nothing;
  perform 1 from public.profiles where id=owner_id for update;
  select start_week into first_week from public.learning_projects where id=p_project;
  if not found then raise exception 'Unknown project';end if;
  if not public.learning_week_unlocked(first_week)then raise exception 'Complete prerequisite weeks before editing this project';end if;
  if p_notes is null or p_url is null then raise exception 'Notes and URL must be text';end if;
  insert into public.learning_project_evidence(user_id,project_id,notes,url)values(owner_id,p_project,trim(p_notes),trim(p_url))
  on conflict(user_id,project_id)do update set notes=excluded.notes,url=excluded.url,updated_at=now();
end;
$$;

create function public.learning_state()
returns jsonb language plpgsql security invoker set search_path='' as $$
declare owner_id uuid:=auth.uid();start_date date;
begin
  if owner_id is null then raise exception 'Sign in first';end if;
  select roadmap_start_date into start_date from public.profiles where id=owner_id;
  return jsonb_build_object(
    'start_date',coalesce(start_date,'2026-11-01'::date),
    'weeks',(select jsonb_agg(row_to_json(r) order by r.number)from(
      select w.*,public.learning_week_unlocked(w.number)as unlocked,
        (select count(*)from public.learning_criteria c where c.week_number=w.number)as total,
        (select count(*)from public.learning_criteria c join public.learning_checks done on done.criterion_id=c.id and done.user_id=owner_id where c.week_number=w.number)as done
      from public.learning_weeks w
    )r),
    'criteria',(select jsonb_agg(row_to_json(r)order by r.week_number,r.position)from(
      select c.*,done.completed_at from public.learning_criteria c left join public.learning_checks done on done.criterion_id=c.id and done.user_id=owner_id
    )r),
    'evidence',(select coalesce(jsonb_agg(row_to_json(r)),'[]'::jsonb)from(select week_number,notes,url from public.learning_evidence where user_id=owner_id)r),
    'projects',(select jsonb_agg(row_to_json(r)order by r.start_week)from(
      select p.*,public.learning_week_unlocked(p.start_week)as unlocked,
        (select count(*)from public.learning_criteria c where c.week_number between p.start_week and p.end_week)as total,
        (select count(*)from public.learning_criteria c join public.learning_checks done on done.criterion_id=c.id and done.user_id=owner_id where c.week_number between p.start_week and p.end_week)as done,
        coalesce(e.notes,'')as notes,coalesce(e.url,'')as url
      from public.learning_projects p left join public.learning_project_evidence e on e.project_id=p.id and e.user_id=owner_id
    )r)
  );
end;
$$;

create function public.learning_next_project()
returns jsonb language sql stable security invoker set search_path='' as $$
  select jsonb_build_object('id',p.id,'title',p.title,'description',p.description,'start_week',p.start_week,'end_week',p.end_week,'unlocked',public.learning_week_unlocked(p.start_week))
  from public.learning_projects p
  where not public.learning_week_unlocked(p.start_week) or exists(select 1 from public.learning_criteria c where c.week_number between p.start_week and p.end_week
    and not exists(select 1 from public.learning_checks done where done.user_id=auth.uid()and done.criterion_id=c.id))
  order by p.start_week limit 1;
$$;

revoke all on function public.learning_week_unlocked(integer),public.set_learning_check(text,boolean),public.save_learning_evidence(integer,text,text),public.save_learning_project(text,text,text),public.learning_state(),public.learning_next_project() from public,anon;
grant execute on function public.learning_week_unlocked(integer),public.set_learning_check(text,boolean),public.save_learning_evidence(integer,text,text),public.save_learning_project(text,text,text),public.learning_state(),public.learning_next_project() to authenticated;
commit;
